//! Authoritative physical geometry derived from the organism's actual structure.
use crate::resources::{BaseResource,Form};use crate::structure::{OrganismStructure,Placement};
#[derive(Clone,Debug,PartialEq)]pub struct PlacedForm{pub unit_index:usize,pub form:Form,pub x:f64,pub y:f64,pub rotation_radians:f64}
#[derive(Clone,Debug,PartialEq)]pub struct OrganismBodyGeometry{pub parts:Vec<PlacedForm>,pub min_x:f64,pub max_x:f64,pub min_y:f64,pub max_y:f64}
impl OrganismBodyGeometry{pub fn from_structure(s:&OrganismStructure,catalog:&[BaseResource])->Option<Self>{if s.units.is_empty(){return None}let mut parts=Vec::new();let(mut min_x,mut max_x,mut min_y,mut max_y)=(f64::INFINITY,f64::NEG_INFINITY,f64::INFINITY,f64::NEG_INFINITY);for(i,u)in s.units.iter().enumerate(){let rigid=u.material.physical_rigid_parts(catalog)?;for(form,local)in rigid{let outer=u.placement;let(sin,cos)=outer.rotation_radians.sin_cos();let p=Placement{x:outer.x+local.x*cos-local.y*sin,y:outer.y+local.x*sin+local.y*cos,rotation_radians:outer.rotation_radians+local.rotation_radians};if !p.x.is_finite()||!p.y.is_finite()||!p.rotation_radians.is_finite(){return None}let Some(r)=form.rigid_bounding_radius()else{continue};min_x=min_x.min(p.x-r);max_x=max_x.max(p.x+r);min_y=min_y.min(p.y-r);max_y=max_y.max(p.y+r);parts.push(PlacedForm{unit_index:i,form,x:p.x,y:p.y,rotation_radians:p.rotation_radians})}}if parts.is_empty(){return None}Some(Self{parts,min_x,max_x,min_y,max_y})}pub fn bounding_box_contains(&self,x:f64,y:f64)->bool{x>=self.min_x&&x<=self.max_x&&y>=self.min_y&&y<=self.max_y}pub fn bounding_radius_about(&self,x:f64,y:f64)->f64{self.parts.iter().map(|p|(p.x-x).hypot(p.y-y)+p.form.rigid_bounding_radius().unwrap_or(0.0)).fold(0.0,f64::max)}}
